import {cpSync,mkdirSync,mkdtempSync,readFileSync,rmSync,writeFileSync} from "node:fs";
import {tmpdir} from "node:os";
import {join,resolve} from "node:path";
import {pathToFileURL} from "node:url";
const root=mkdtempSync(join(tmpdir(),"jadpo-rm304-independent-"));
const text=readFileSync("tests/compile/pass/170_checked_service_operation.jadpo","utf8");
const appPath=join(root,"app.jadpo");
mkdirSync(join(root,"tests/assurance"),{recursive:true});
cpSync("tests/assurance/service-reference-mail-v0.1.json",join(root,"tests/assurance/service-reference-mail-v0.1.json"));
const compiler=resolve("jadpo/target/debug/jadpo");
const variants={
empty_fake:text.replace(/(fixture service_accepted \{[\s\S]*?service ReminderMail: fake \{)[\s\S]*?(\n    \}\n\})/,"$1$2"),
unknown_operation:text.replace("send_overdue_reminder => accept","send_message => accept"),
unknown_outcome:text.replace("=> provider.rate_limited","=> provider.unlisted"),
wrong_response:text.replace("=> accept ReminderReceipt","=> accept ReminderMessage"),
missing_fake:text.replace("using service_accepted {","{"),
duplicate_fake:text.replace("fixture service_accepted {","fixture service_accepted { service ReminderMail: fake {}"),
secret_response:text.replace('accepted_at: Instant("2026-01-15T12:00:00Z")','accepted_at: config.mail_api_key'),
wrong_request:text.replace("call classify_delivery(mail)","call classify_delivery(none)")
};
let connects=0;
const originalConnect=Bun.connect;
const originalFetch=globalThis.fetch;
const previousEnv=process.env.NODE_ENV;
const previousLog=console.error;
try {
process.env.NODE_ENV="test";
for(const [name,source] of Object.entries(variants)){
writeFileSync(appPath,source);
const checked=Bun.spawnSync([compiler,"check",root,"--diagnostic-format=json"],{stdout:"pipe",stderr:"pipe"});
const report=JSON.parse(checked.stdout.toString());
console.log(JSON.stringify({case:name,status:report.status,codes:report.diagnostics.map((d:any)=>d.code)}));
if(name==="empty_fake"&&checked.exitCode===0){
const built=Bun.spawnSync([compiler,"build",root],{stdout:"pipe",stderr:"pipe"});
if(built.exitCode!==0)throw new Error(built.stderr.toString());
Bun.connect=(()=>{connects++;return Promise.reject(new Error("independent review blocked provider connection"));}) as typeof Bun.connect;
globalThis.fetch=(async()=>{throw new Error("independent review blocked fetch");}) as typeof fetch;
const logs:string[]=[];
console.error=(line:any)=>logs.push(String(line));
const app=await import(pathToFileURL(join(root,"build/target/app.ts")).href);
const result=await app.runTests();
console.error=previousLog;
console.log(JSON.stringify({case:"empty_fake_runtime",status:result.status,summary:result.summary,blockedProviderConnections:connects,secretInReport:JSON.stringify(result).includes("fixture-only-provider-key"),secretInLogs:logs.join("\n").includes("fixture-only-provider-key")}));
Bun.connect=originalConnect;
globalThis.fetch=originalFetch;
}
}
}finally{
Bun.connect=originalConnect;
globalThis.fetch=originalFetch;
console.error=previousLog;
if(previousEnv===undefined)delete process.env.NODE_ENV;else process.env.NODE_ENV=previousEnv;
rmSync(root,{recursive:true,force:true});
}

